import{_ as o,c as r,o as p,ah as a}from"./chunks/framework.BxT5r71R.js";const h=JSON.parse('{"title":"BMSG创立之初便怀抱的梦想：Novel Core日本武道馆演出的意义","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART3/3_BMSG创立之初便怀抱的梦想：Novel Core日本武道馆演出的意义.md","filePath":"zh-cn/Management2/PART3/3_BMSG创立之初便怀抱的梦想：Novel Core日本武道馆演出的意义.md"}'),t={name:"zh-cn/Management2/PART3/3_BMSG创立之初便怀抱的梦想：Novel Core日本武道馆演出的意义.md"};function n(C,e,_,l,s,i){return p(),r("div",null,[...e[0]||(e[0]=[a('<p>► 2024/01</p><h2 id="bmsg创立之初便怀抱的梦想-novel-core日本武道馆演出的意义" tabindex="-1">BMSG创立之初便怀抱的梦想：Novel Core日本武道馆演出的意义 <a class="header-anchor" href="#bmsg创立之初便怀抱的梦想-novel-core日本武道馆演出的意义" aria-label="Permalink to &quot;BMSG创立之初便怀抱的梦想：Novel Core日本武道馆演出的意义&quot;">​</a></h2><p>#总体规划 #Novel Core #梦想 #沟通 #引导</p><h3 id="如果其中夹杂着-大人的盘算-观众是能感受到的。尤其是年轻人-也许他们自己并未意识到-却会敏锐地察觉出来。" tabindex="-1">“如果其中夹杂着‘大人的盘算’，观众是能感受到的。尤其是年轻人，也许他们自己并未意识到，却会敏锐地察觉出来。” <a class="header-anchor" href="#如果其中夹杂着-大人的盘算-观众是能感受到的。尤其是年轻人-也许他们自己并未意识到-却会敏锐地察觉出来。" aria-label="Permalink to &quot;“如果其中夹杂着‘大人的盘算’，观众是能感受到的。尤其是年轻人，也许他们自己并未意识到，却会敏锐地察觉出来。”&quot;">​</a></h3><p><strong>2024年1月17日，在22岁生日的前一天，Novel Core登上日本武道馆，举行个人专场演出。他用精彩的舞台完整讲述了自己一路走来的故事。与BMSG旗下艺人们一同坐在观众席上的SKY-HI，时而挥拳，时而欢呼，有时还流下眼泪，始终注视着Novel Core。</strong></p><p><strong>Novel Core观看SKY-HI于2017年举行的日本武道馆演出后，便梦想着有一天站上这座舞台。2020年，他成为BMSG创立后签约的首位艺人；BMSG当时提出的理念是“不要扼杀才华”。此后，两人朝着“梦想”一步一步走来。本次采访在日本武道馆演出结束约10小时后进行。我们请SKY-HI谈了谈兴奋之情尚未消退时的感受。</strong></p><p>一开始，我还想着：“我是不是也要站上（日本武道馆的）舞台？”但Core（Novel Core）说：“这次你别上台，在（观众席）看就好。”（笑）既然难得有机会当观众，我便在事先完全不知道舞台制作和演出曲目的情况下观看了整场演出。</p><p>演出开始前，我想去后台送他一份大一点的礼物，既作为生日礼物，也作为庆祝日本武道馆演出的贺礼。不过，Core自己一点点建立起来的信任，让我完全不担心整个团队。而且，我知道Core在这种时候很有力量，也一定会放手去做自己想做的事，因此一直很期待。</p><p>Core出现在日本武道馆舞台上的那一刻，也意味着BMSG创立之初的一个目标实现了。很少有哪一次演出，能让我在开场的瞬间就感受到如此强烈的成就感。我从头到尾都单纯地兴奋地看着，同时也想起了许多事情。</p><p>对3年前的Core和我来说，“3年后登上日本武道馆”是已经确定的事。毕竟，Core对日本武道馆怀有非同寻常的感情，我也回答他说：“这一定能做到。”但并不是Core说服了我，而是因为那个梦想本身在我看来就非常现实。所以，我们一直理所当然地反复确认：“要站上日本武道馆，还缺少这些方面，那就这样做吧。”昨天晚上，我再次意识到，原来自己一直身处“追逐梦想这个梦想”之中。</p><p>我一直强烈地感受到“怀抱梦想”这类“美好理想”的重要性。小时候，每个人都会像Core一样怀抱大梦想，但随着年岁增长，人总会在某个时候渐渐失去做梦的能力。而且，即使有梦想，也不一定能够实现。即便实现了一个宏大的目标，也无法确定它最终是否会带来幸福。</p><p>不过，比起“梦想无法实现”这个结果，更糟糕的是先认定“说不定实现不了”，从而削弱追逐梦想的力量，无法相信梦想并放手一搏。那样不仅会留下遗憾，给自己留好退路后再失败，也很难从中学到什么；更不用说，梦想实现的概率本身也会大幅降低。</p><p>我认为，提高梦想实现可能性的第一步，就是坚定地相信梦想能够实现。如果真心相信，并能想象自己实现梦想时的样子，通往梦想的路径以及所需付出的努力就会清晰地浮现出来，接下来只要朝着那个方向努力就好。我想，没有比这更重要的事了。即使在别人看来，那是荒诞不经的事，只要自己相信，就一定存在实现的可能。</p><h3 id="core的成功是绝对必要的" tabindex="-1">Core的成功是绝对必要的 <a class="header-anchor" href="#core的成功是绝对必要的" aria-label="Permalink to &quot;Core的成功是绝对必要的&quot;">​</a></h3><p>Core始终没有在这一点上动摇过。所以，即使经历了许多痛苦，他也从未迷失梦想，更没有放弃梦想。我也是一样。既然Core自己相信，我就没有怀疑的余地。因此，只要是Core想做的事，我都毫不犹豫，也毫无畏惧地全力支持。</p><p>能让Core一直纯粹地怀抱梦想，并和他一起坚持到梦想实现，真的是一段无比珍贵的经历。真的痛苦到难以承受时，放弃梦想自然会轻松一些，我也认为那样的生活方式同样是一种正确选择。但我们一直追逐着梦想。</p><p>不过，我们也不是一路咬紧牙关、紧抿嘴唇走过来的。回头看，这3年里有哭有笑，一直都很开心。</p><p>拥有梦想，朝着梦想努力，并最终实现它，说起来很简单，但我自己非常清楚，这其实是极其艰难的事。可是，能从他人身上感受到这种珍贵，机会并不多。我现在感受到的这份“喜悦”，或许正是因为能够体会到这份珍贵。</p><p><strong>这一次，Novel Core成功实现了自BMSG创立之初便存在的“梦想”——在日本武道馆举行个人专场演出；此外，他还在自己口中的“英雄”SKY-HI的支持下，发行了歌曲《HERO》。其中也能感受到他想亲自引领下一代的意志。</strong></p><p><strong>SKY-HI笑着说：“想到今后终于履行了登上日本武道馆这一必达目标的责任，可以单纯地观看Core的演出，我就很期待。”此刻，亲眼见证Core显然正迈向下一个阶段，也再次清楚地证明了“作为BMSG第一位艺人，Novel Core所具有的意义”。</strong></p><p>我和Core之间的关系，在BMSG内部确实很特殊。因为在创立厂牌时，他是第一个来到一无所有的我们身边的艺人。我认为，他能否取得成功，是一件非常重要的事，也关系到别人对我作为一个人的各种信任。包括我当初判断“第一位艺人应该是Novel Core”的眼光，以及作为经纪公司社长所获得的信任。</p><p>培养自己认定的才能，带着他一步一步走向更大的舞台，也许是每一家娱乐经纪公司社长的工作。但对我来说，因为还直接参与制作，所以很容易把重心放在“打造并推广一个组合”上。</p><p>可是，“把一个组合扎实地推广出去”和“不让Novel Core这样的才能埋没”，需要做的事情有很大不同。后者是BMSG之所以成为BMSG所真正不可或缺的事情。</p><p>从这个意义上说，这次演出对BMSG来说确实是一件大事。我虽然说过“很开心”，但看完Core的日本武道馆演出后，也感觉自己像亲自演出了一场那样，累得筋疲力尽。（笑）不过，这真的太精彩了，简直难以用言语形容。说到“难以用言语形容”，这个词说出口时听起来还真是悦耳啊！</p><p>这不仅适用于Core，也适用于所有个人艺人。对Core来说，日本武道馆绝不能成为一座“被安排着站上去的舞台”。比如，我不会介入作曲、舞台演出和演出曲目等“艺人实务”。我会提供建议和各种反馈，但所有决定都由艺人本人做出。不应该有任何来自本人意志之外的东西介入其中。</p><p>如果其中夹杂着“大人的盘算”，观众是能感受到的。尤其是年轻人，也许他们自己并未意识到，却会敏锐地察觉出来。</p><p>当然，从我作为一个成年人的立场来看，也会有觉得“这样做不是更好吗”的时候。尤其在Core的情况下，过去3年里，似乎有不少让我为此苦恼的阶段。</p><p>具体情况，既然日本武道馆演出已经结束了，或许有一天Core会亲自讲出来。但我记得很清楚，有两次特别大的危机。第一次是在发行《THANKS, ALL MY TEARS》（2021年）前大约3个月，当时Core承受着压力和不安。这一次，是Core主动提出来的，所以我请他休息了一段时间。至于另外一次，暂时保密。（笑）</p><p>当然，我们平时沟通很多，细枝末节的问题也会随时出现。但对我来说，Core把自己创作的歌曲拿给我听，或者拿什么给我看，每一次都是无上的喜悦。所以，我和他之间自然会有很多积极的创作讨论，比如“做得不错，接下来我们这样做吧”“试试看那个吧”。</p><h3 id="个人艺人所拥有的可能性" tabindex="-1">个人艺人所拥有的可能性 <a class="header-anchor" href="#个人艺人所拥有的可能性" aria-label="Permalink to &quot;个人艺人所拥有的可能性&quot;">​</a></h3><p>因为我自己也是个人艺人，所以有些事情只有站在这个位置上才能看见。甚至可以说，他们帮助我建立了站上舞台的意义，也塑造了我的全部背景。</p><p>比如，我站上舞台时，会意识到他们正在注视着自己；这些年来，我一直是在这种意识下进行表演的。这不就是所谓的“给他们看自己的背影”吗？另一方面，我也深深感到，自己的“背影”同样是他们帮我塑造出来的。我想，这就是一种相互作用。</p><p>在音乐方面也是一样。我带给大家的影响，以及我从大家那里学到、得到的东西，分量应该差不多。可以说，正因为有我，Core才能在这个时间点站上日本武道馆；但也可以说，正因为有Core，我才能培养出一位登上日本武道馆的艺人。没有谁在前，也没有谁在后。人与人的相遇，或许就是这样。</p><p>关于Core的未来，我们正在筹划一些事情。不过，这些内容不该由我来宣布，可以请大家等Core亲自告诉你们吗？</p><p>“在20多岁期间登上巨蛋”，这个可以说吗？（BMSG宣布成立的线上演出）《老家个人专场》（2020年9月26日）结束后，我回到家里，和Core以及从那时起就一直给予BMSG支持与期待的Chanmina，我们三个人聊了起来。那时就谈到了这件事。</p><p>对Core来说，距离30岁还有整整7年，所以我想和他一起努力。</p><p>还有一件事，我觉得可以由我来说：我感觉SKY-HI、Novel Core、Aile The Shota、edhiii boi和REIKO这几位个人艺人，真的全都已经准备好了，所以我想让大家一起做点什么。</p><p>我们旗下的个人艺人站在一起时，每个人的性格都截然不同，实在有趣得不得了。（笑）这种人物个性的趣味、创作能力和作品质量，都应该进一步展现出来，留下具体成果。我有一种感觉，那最终会成为值得全世界骄傲的东西。</p><p>这和大家大概想象的“男子组合走向世界”完全是另一种故事，但我从中感受到了巨大的可能性。让个人艺人充分展现各自自由拥有的艺术形式（art form），我觉得这也会提高打造全球热门作品的可能性。观察最近的音乐潮流，我也越来越有这种感觉。</p><p>而且，正因为每个人的优势各不相同，彼此碰撞产生化学反应、作品发展的可能性也会更大……可以说，我们确实有不少胜算。不过，比起这些，更准确的说法或许是：那种纯粹的兴奋感，根本停不下来。</p>',40)])])}const c=o(t,[["render",n]]);export{h as __pageData,c as default};
